'use strict';
const paths={personal:{label:'YOUR STARTING POINT / PERSONAL TAX',title:'A return you can feel informed about.',description:'Get help organizing your filing needs, understanding your return, and asking the questions that matter to you.',items:['Individual & family tax preparation','A conversation about your situation','Virtual service that fits your day'],action:"Let's talk about your return"},self:{label:'YOUR STARTING POINT / SELF-EMPLOYED',title:'Your work. Your numbers. More clarity.',description:'Freelancing, contracting, or running a solo business? Start with a conversation about your income, records, and filing needs.',items:['Self-employed tax preparation','Help identifying the records to gather','Bookkeeping support to discuss'],action:"Let's talk about self-employment"},business:{label:'YOUR STARTING POINT / BUSINESS SUPPORT',title:'Build your business on clearer numbers.',description:'Choose support for the stage you are in, from organizing the books to planning the next chapter of your business.',items:['Ongoing or catch-up bookkeeping','Payroll, reporting & budgeting','Business formation guidance'],action:"Let's talk about your business"}};
function selectPath(key){const p=paths[key];if(!p)return;document.querySelectorAll('[data-path]').forEach(b=>{const active=b.dataset.path===key;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.getElementById('path-label').textContent=p.label;document.getElementById('path-title').textContent=p.title;document.getElementById('path-description').textContent=p.description;document.getElementById('path-list').replaceChildren(...p.items.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));const action=document.getElementById('path-action');action.replaceChildren(document.createTextNode(p.action+' '));const arrow=document.createElement('span');arrow.setAttribute('aria-hidden','true');arrow.textContent='↗';action.append(arrow);}
document.querySelectorAll('[data-path]').forEach(b=>b.addEventListener('click',()=>selectPath(b.dataset.path)));
document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>selectPath(a.dataset.select)));
const menu=document.querySelector('.menu-toggle'),navigation=document.getElementById('navigation');function closeMenu(){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open');}menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open);});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){closeMenu();menu.focus();}});
const checks=[...document.querySelectorAll('.checklist input')];checks.forEach(input=>input.addEventListener('change',()=>{const n=checks.filter(c=>c.checked).length;document.getElementById('check-progress').textContent=`${n} of ${checks.length} ready`;document.getElementById('progress-bar').style.width=`${n/checks.length*100}%`;}));
document.getElementById('download-list').addEventListener('click',()=>{const text='SLS ACCU-BOOKS | APPOINTMENT STARTER CHECKLIST\n\n[ ] Identification and household details\n[ ] Income documents (W-2s, 1099s, and other relevant records)\n[ ] Last year\'s return, if available\n[ ] Relevant expense and deduction records\n[ ] Your questions\n\nYour document needs depend on your situation. Confirm additional requirements during your appointment.\nDo not send sensitive tax records by ordinary email. Use the designated secure intake service.\n\nContact: ssims@slsaccubooks.com\nWebsite: https://www.slsaccubooks.com/\n';const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='SLS_AccuBooks_Appointment_Checklist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
const privacy=document.getElementById('privacy-dialog');document.getElementById('privacy-open').addEventListener('click',()=>privacy.showModal());document.querySelector('.dialog-close').addEventListener('click',()=>privacy.close());privacy.addEventListener('click',e=>{if(e.target===privacy){const r=privacy.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)privacy.close();}});
document.getElementById('year').textContent=new Date().getFullYear();
if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));}
